P=pathlib.Path(__file__).parent;R=P.resolve().parents[6];J=json.load(open(R/'src/data/manufacturing/surface.json'))['lessons'][54:57]
D=[('आसंजन, कठोरता और सोल्डर वेटेबिलिटी के परीक्षण अलग करें','जाँचने वाले गुण और विधि मिलाएँ।\nविनाशकारी प्रभाव और नमूना नियंत्रण जाँचें।',[
('आसंजन में इंटरफेस की स्थिति सोचें','आसंजन परीक्षण परत और आधार के जुड़ाव की मजबूती जाँचता है। टेप पील, मोड़ना, फाइल और तापीय आघात अलग प्रभाव देते हैं, इसलिए सभी का परिणाम समान जरूरी नहीं। निर्धारित विधि, नमूना और निर्णय मानदंड जाँचें।'),
('कठोरता और सोल्डर वेटेबिलिटी अलग करें','कठोरता परीक्षण इंडेंटेशन आदि के प्रतिरोध को जाँचता है। माइक्रोविकर्स, रॉकवेल और ब्रिनेल जैसी विधियाँ हैं। जिम्मेदार व्यक्ति मापन भार, सतह और परत मोटाई के अनुकूल विधि चुनता है। सोल्डर वेटेबिलिटी सतह पर सोल्डर फैलने की अवस्था आदि आँकती है; केवल कठोरता या रंग उसका विकल्प नहीं।'),
('परीक्षित नमूना मूल उत्पाद में न मिलाएँ','मोड़, खरोंच, गर्मी या रसायन का प्रभाव लगने पर नमूना मूल शिपमेंट अवस्था में वापस न आ सकेगा। नमूना योजना और पहचान मानें; परीक्षित वस्तु को अप्रयुक्त अच्छे उत्पाद में न मिलाएँ। विधि की अनुकूलता और उत्पाद का पास-फेल निर्धारित मानदंड से तय करें।'),
('अतिरिक्त विनिर्देश जाँचें','संपर्क पार्ट का रंग और मोटाई पास हो, फिर भी जोड़ने की माँग हो तो निर्धारित सोल्डर वेटेबिलिटी जाँच न छोड़ें। ऑपरेटर स्वयं गर्म करने की शर्त से परीक्षण न करे; गुणवत्ता जिम्मेदार व्यक्ति से नमूना और विधि पूछें।')],['परत और आधार के जुड़ाव का गुण।','इंडेंटेशन आदि के प्रतिरोध का सूचक।','सतह पर सोल्डर के गीला करके फैलने का गुण।','नमूना बदलकर या क्षतिग्रस्त करके मूल्यांकन करने का परीक्षण।'],'शब्द4मिनट, तीन गुण8मिनट, विधि और नमूना8मिनट, संपर्क पार्ट उदाहरण7मिनट;3मिनट में परीक्षित वस्तु की पहचान लिखें।',['गर्मी या रसायन का परीक्षण स्वयं निर्णय से न करें।','मोड़े या परीक्षित पार्ट अप्रयुक्त वस्तुओं में वापस न रखें।'],'परीक्षण का उद्देश्य और लगाया प्रभाव अलग करें।\nदिखावट पास होने से अन्य प्रदर्शन परीक्षण न बदलें।'),
('प्रदूषण के प्रकार और रासायनिक जानकारी के स्रोत अलग करें','जल और वायु के अलावा पर्यावरण प्रभाव भी व्यवस्थित करें।\nRoHS औरREACH के उद्देश्य न मिलाएँ।',[
('कई रास्तों से प्रभाव देखें','प्रदूषण अध्ययन में जल, वायु और मिट्टी प्रदूषण, शोर, कंपन, भूमि धँसना और दुर्गंध अलग हैं। केवल पारदर्शी अपशिष्ट जल या कम गंध से पूरे कारखाने का प्रभाव शून्य नहीं मान सकते। फर्श रिसाव और कचरे का स्थानांतरण भी रिकॉर्ड करें; रोकथाम और कमी सोचें।'),
('उत्पाद के पदार्थ और कार्यस्थल उत्सर्जन अलग हैं','RoHS विद्युत और इलेक्ट्रॉनिक उपकरणों में कुछ खतरनाक पदार्थों के उपयोग प्रतिबंध कीEU व्यवस्था है। यह कार्यस्थल के अपशिष्ट जल का नियंत्रण मान नहीं। जिम्मेदार व्यक्ति विषय उत्पाद, सामग्री और छूट आदि समेत वर्तमान आवश्यकताएँ जाँचे; केवल रसायन के नाम से अनुकूलता घोषित न करें।'),
('REACH को केवल पंजीकरण न मानें','REACH रासायनिक पदार्थों का पंजीकरण, मूल्यांकन, प्राधिकरण और प्रतिबंध शामिल करने वालीEU व्यवस्था है। भूमिका के अनुसार सूचना संचार और उपयोग की शर्तें भी संबंधित हैं। इसका अर्थ “उत्पाद की पूरी जानकारी पंजीकृत हो तो कुछ भी प्रयोग कर सकते हैं” नहीं। वास्तविक दायित्व पदार्थ, मात्रा और आपूर्ति में भूमिका आदि पर निर्भर हैं; वर्तमान दस्तावेज से जाँचें।'),
('बदलाव पर मिलान','ग्राहक पदार्थ सामग्री की पुष्टि माँगे तो विषय पार्ट नंबर, संस्करण, घटक सूचना, आपूर्तिकर्ता प्रमाण और लागू शर्तें जिम्मेदार व्यक्ति को व्यवस्थित दें। केवलSDS से हर माँग पूरी न मानें; जरूरी दस्तावेज और विश्लेषण जाँचें। पाठ वास्तविक कानूनी अनुकूलता निर्णय का विकल्प नहीं।')],['स्वास्थ्य या रहने के वातावरण को नुकसान पहुँचाने वाला प्रदूषण आदि।','उत्पाद या सामग्री में मौजूद पदार्थ।','विद्युत-इलेक्ट्रॉनिक उपकरण के कुछ खतरनाक पदार्थों के प्रतिबंध कीEU व्यवस्था।','रसायनों के पंजीकरण, मूल्यांकन, प्राधिकरण और प्रतिबंध आदि कीEU व्यवस्था।'],'शब्द4मिनट, सात प्रभाव8मिनट, दो व्यवस्थाएँ8मिनट, ग्राहक के प्रश्न का उदाहरण7मिनट;3मिनट में कार्यस्थल उत्सर्जन से अंतर लिखें।',['केवल पाठ से कानून या ग्राहक विनिर्देश की अनुकूलता घोषित न करें।','अज्ञात द्रव मिलाकर या बहाकर जाँच न करें।'],'पर्यावरण प्रभाव के रास्ते और उत्पाद के पदार्थ अलग करें।\nकेवल व्यवस्था के नाम से अनुकूलता निश्चित न करें; वर्तमान आवश्यकताएँ जाँचें।'),
('परत बनाने की विधि और उद्देश्य से सतह उपचार तुलना करें','परत जोड़ने और सतह बदलने के उपचार अलग करें।\nकेवल प्रतिनिधि मोटाई से विधि न चुनें।',[
('निर्माण विधि और कार्य अलग करें','धातु परत की प्लेटिंग, आधार की सतह ऑक्सीकृत करने वाला एनोडाइजिंग, रासायनिक अभिक्रिया से यौगिक परत वाला कन्वर्जन उपचार और रेजिन आदि पेंट की पेंटिंग की निर्माण विधियाँ अलग हैं। थर्मल स्प्रे, एचिंग, पॉलिशिंग, क्वेंचिंग और नाइट्राइडिंग भी सतह बदलते हैं; सभी को प्लेटिंग न कहें।'),
('आधार और अनुप्रयोग जाँचें','रेजिन जैसे अधातु पर भी धातु परत लगाने की विधियाँ हैं, पर उपयुक्त पूर्व उपचार और सामग्री की शर्तें चाहिए। एनोडाइजिंग हर धातु पर समान शर्तों में नहीं होता। सामग्री नाम, अंडरकोट, सबसे बाहरी परत और विद्युत या तापीय शर्तें मिलाएँ।'),
('तुलना तालिका की सीमा विनिर्देश नहीं','पुस्तक की मोटाई सीमाएँ और उपयोग उदाहरण विधियों की तुलना के संदर्भ हैं। प्लेटिंग, एनोडाइजिंग, कन्वर्जन और पेंटिंग की सामान्य मोटाई को किसी उत्पाद की पास सीमा या उपकरण सेटिंग न बनाएँ। दिखावट, संक्षारण, घिसाव, जोड़ और विद्युत गुणों की आवश्यकताओं को निरीक्षण तक जोड़ें।'),
('उपयोग बदलने पर मिलान','पार्ट सजावट से विद्युत संपर्क उपयोग में बदले तो समान रंग वाला उपचार चुनना पर्याप्त नहीं। चालकता और संपर्क, परत संरचना, घिसाव और संक्षारण की माँग जिम्मेदार व्यक्ति से जाँचें; स्वीकृत प्रक्रिया चुनें।')],['सतह पर आवश्यक परत बनाना।','सामग्री गर्म करके छिड़कने आदि से परत बनाने की विधि।','रासायनिक आदि विधि से सतह हटाना या संसाधित करना।','किसी विधि के उपयोग का प्रतिनिधि उदाहरण।'],'शब्द4मिनट, चार विधियाँ8मिनट, आधार और मोटाई तालिका8मिनट, बदले उपयोग का उदाहरण7मिनट;3मिनट में विनिर्देश और संदर्भ का अंतर लिखें।',['विधि नाम या संदर्भ मोटाई से वास्तविक उपकरण की शर्तें न तय करें।','उपचार बदलाव के लिए सामग्री, प्रक्रिया और गुणवत्ता की स्वीकृति लें।'],'वर्गीकरण में परत बनने की विधि और आधार जाँचें।\nतुलना तालिका का संदर्भ और उत्पाद विनिर्देश अलग हैं।')]
